node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W7231611';
const oldItemId = '3301828484';
const newItemId = '7389318502';
const paymentMethodId = 'credit_card_9958253';

// Verify order status
const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
if (order.status !== 'delivered') throw new Error('Order not delivered');

// Get old item price
const oldItem = db.prepare('SELECT * FROM order_items WHERE order_id = ? AND item_id = ?').get(orderId, oldItemId);
if (!oldItem) throw new Error('Old item not found in order');

// Get new variant price and availability
const newVariant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ?').get(newItemId);
if (!newVariant || !newVariant.available) throw new Error('New variant not available');

const diffPrice = Math.round((newVariant.price - oldItem.unit_price) * 100) / 100;
console.log('Price difference:', diffPrice);

// Update order status and exchange fields
db.prepare(\`
  UPDATE orders SET 
    status = 'exchange requested',
    exchange_items = ?,
    exchange_new_items = ?,
    exchange_payment_method_id = ?,
    exchange_price_difference = ?
  WHERE order_id = ?
\`).run(
  JSON.stringify([oldItemId]),
  JSON.stringify([newItemId]),
  paymentMethodId,
  diffPrice,
  orderId
);

console.log('Order updated to exchange requested');

// Verify the update
const updated = db.prepare('SELECT order_id, status, exchange_items, exchange_new_items, exchange_payment_method_id, exchange_price_difference FROM orders WHERE order_id = ?').get(orderId);
console.log('\n=== UPDATED ORDER ===');
console.log(JSON.stringify(updated, null, 2));

db.close();
console.log('\nExchange completed successfully!');
"
